-- ============================================================================
-- Creative Factory — ingestion registre briques  (public.factory_bricks)
-- Source : usine/catalogue-briques.md + usine/registres.md
-- Idempotent : INSERT ... ON CONFLICT (id) DO UPDATE.
-- COMPTES : 66 hooks, 15 CTA, 66 contenus Cartoon (C12→C77).
-- IDs Cartoon = C<N> numériques : AUCUNE collision avec C-OMNI-* / C-IMGIA-* / C-CLAUDE-*.
-- Fidélité : compatible_subjects = valeurs LITTÉRALES du tableau (la règle
--   « image-ia ⟺ express auto » n'est PAS appliquée ici pour ne rien deviner).
-- 'generique' = hook GÉNÉRIQUE (compatible ~tous sujets).
-- ============================================================================

-- Hooks parlés (66) --------------------------------------------------------
ON CONFLICT (id) DO UPDATE SET label=excluded.label, subject=excluded.subject, meta=excluded.meta, updated_at=now();

-- CTA (15 canoniques) ------------------------------------------------------
-- Aucun script textuel dans la source -> meta.script = null.
-- avatar_required : true par défaut (règle « l'avatar ouvre ET ferme » /
--   hook.avatar == cta.avatar) ; false pour la CTA libre DM (format non parlé).
ON CONFLICT (id) DO UPDATE SET label=excluded.label, subject=excluded.subject, meta=excluded.meta, updated_at=now();

-- Contenus Cartoon (66 : C12→C77) -----------------------------------------
-- meta.status : rendu (montage livré) | audio-seul (audio ok, montage à fournir) | vide (à enregistrer).
-- C65 : listé À LA FOIS en audio-seul (C63→C72) et en vide (mention explicite) -> tranché 'vide'.
ON CONFLICT (id) DO UPDATE SET label=excluded.label, subject=excluded.subject, meta=excluded.meta, updated_at=now();
